It always the battle and we can provide a single object for all the route option. Certainly not adding it one by one.

```js
function ReadOnly(obj) {
  return new Proxy(obj, {
    get(target, prop) {
      consst value = target[prop]
      if(typeof value === 'object' && value !== null) {
        return ReadOnly(value)
      }
      return value
    },
    set() {
      // once it comes to `request` context, route option should not be mutate
      return true
    }
  })
}
